head.b:skin:
/* --------------------------------------------------------------------------
 * EditorialVocab Minimalist Premium Theme CSS (Short Card Form & Dual Tags)
 * -------------------------------------------------------------------------- */
:root {
  --bg-main: #0b0f19;
  --bg-card: #131b2e;
  --bg-card-hover: #1c2742;
  --border-color: #1e293b;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --accent-indigo: #6366f1;
  --accent-emerald: #10b981;
  --font-hindi: 'Hind', sans-serif;
  --font-body: 'Plus Jakarta Sans', sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body { background-color: var(--bg-main); color: var(--text-main); font-family: var(--font-body); line-height: 1.6; min-height: 100vh; }
a { color: var(--accent-indigo); text-decoration: none; transition: color 0.2s ease; }
a:hover { color: #a5f3fc; }

/* Sticky Clean Navigation Bar */
.site-navbar { background: rgba(19, 27, 46, 0.95); backdrop-filter: blur(12px); border-bottom: 1px solid var(--border-color); position: sticky; top: 0; z-index: 100; padding: 14px 20px; }
.nav-container { max-width: 1200px; margin: 0 auto; display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.brand-logo { display: flex; align-items: center; gap: 10px; font-weight: 800; font-size: 20px; color: #fff; text-decoration: none; }
.brand-logo span { background: linear-gradient(135deg, var(--accent-indigo), #4f46e5); padding: 4px 10px; border-radius: 8px; font-size: 13px; text-transform: uppercase; color: #fff; }

.nav-links { display: flex; gap: 24px; list-style: none; margin: 0; padding: 0; }
.nav-links a { color: var(--text-muted); font-size: 14px; font-weight: 700; }
.nav-links a:hover { color: #fff; }

/* Header Title Area */
.site-hero { background: linear-gradient(135deg, #1e1b4b 0%, #0f172a 100%); border-bottom: 1px solid var(--border-color); padding: 36px 20px; text-align: center; }
.hero-title { font-size: 28px; font-weight: 800; color: #fff; margin-bottom: 6px; }
.hero-sub { font-size: 15px; color: var(--text-muted); max-width: 600px; margin: 0 auto; }

/* Main Grid Layout */
.main-layout { max-width: 1200px; margin: 30px auto; padding: 0 20px; display: grid; grid-template-columns: 1fr 300px; gap: 30px; }
.content-area { min-width: 0; }
.sidebar-area { min-width: 0; }

/* 2-Column Grid Layout for Homepage Post Cards */
.blog-posts-grid-container { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 20px; }

/* Clean Short Post Card Item */
.post-card-item { background: var(--bg-card); border: 1px solid var(--border-color); border-radius: 16px; padding: 20px; display: flex; flex-direction: column; justify-content: space-between; transition: transform 0.2s ease, border-color 0.2s ease; cursor: pointer; text-decoration: none; position: relative; }
.post-card-item:hover { border-color: var(--accent-indigo); transform: translateY(-3px); }
.post-card-title { font-size: 18px; font-weight: 800; margin-bottom: 10px; line-height: 1.35; }
.post-card-title a { color: #fff; text-decoration: none; }
.post-card-title a:hover { color: #a5f3fc; }

.post-meta { font-size: 12px; color: var(--text-muted); display: flex; flex-wrap: wrap; items-align: center; gap: 6px; margin-bottom: 12px; }
.tag-badge { background: rgba(99, 102, 241, 0.15); border: 1px solid rgba(99, 102, 241, 0.3); color: #a5f3fc; font-size: 11px; font-weight: 800; padding: 2px 8px; border-radius: 10px; }
.tag-badge.month { background: rgba(16, 185, 129, 0.15); border-color: rgba(16, 185, 129, 0.3); color: #34d399; }

/* Truncated Short Snippet Text on Homepage Cards */
.post-snippet-text { font-size: 13.5px; color: #cbd5e1; line-height: 1.5; margin-bottom: 16px; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; height: 60px; }

.btn-read-article { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 700; color: var(--accent-indigo); margin-top: auto; }
.btn-read-article:hover { color: #a5f3fc; }

/* Single Post Full Page Display */
.single-post-page .post-card-item { cursor: default; }
.single-post-page .post-snippet-text { display: block; height: auto; -webkit-line-clamp: unset; font-size: 15px; }

/* Sidebar Widgets */
.widget-box { background: var(--bg-card); border: 1px solid var(--border-color); border-radius: 16px; padding: 20px; margin-bottom: 20px; }
.widget-title { font-size: 15px; font-weight: 800; border-bottom: 2px solid var(--accent-indigo); padding-bottom: 6px; margin-bottom: 14px; color: #fff; text-transform: uppercase; }

/* Monthly Filter Grid List */
.months-filter-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; list-style: none; }
.month-filter-link { background: #0f172a; border: 1px solid var(--border-color); color: var(--text-main); padding: 8px; border-radius: 8px; font-size: 13px; font-weight: 700; text-align: center; display: block; transition: all 0.2s ease; }
.month-filter-link:hover { border-color: var(--accent-indigo); background: rgba(99, 102, 241, 0.15); color: #a5f3fc; }

/* Footer Pages Navigation */
.site-footer { background: #090d16; border-top: 1px solid var(--border-color); padding: 36px 20px; margin-top: 50px; text-align: center; }
.footer-pages-nav { display: flex; justify-content: center; gap: 20px; margin-bottom: 16px; flex-wrap: wrap; }
.footer-pages-nav a { color: var(--text-muted); font-size: 14px; font-weight: 600; }
.footer-pages-nav a:hover { color: var(--accent-emerald); }
.copyright-text { font-size: 13px; color: #64748b; }

/* Mobile Responsive Rules */
@media (max-width: 800px) {
  .main-layout { grid-template-columns: 1fr; }
  .blog-posts-grid-container { grid-template-columns: 1fr; }
  .hero-title { font-size: 22px; }
  .nav-links { gap: 14px; flex-wrap: wrap; }
  .nav-links a { font-size: 13px; }
}
